<script setup lang="ts">
import { ref, computed, onBeforeUnmount } from 'vue'; import Drawer from './Drawer.vue';
defineProps<{ busy?: boolean; failure?: string }>(); const emit = defineEmits<{ close: []; save: [file: File, crop: { x: number; y: number; size: number }] }>();
const file = ref<File>(); const source = ref(''); const width = ref(1); const height = ref(1); const zoom = ref(1); const horizontal = ref(0.5); const vertical = ref(0.5); const error = ref(''); let active = true;
const shortSide = computed(() => Math.min(width.value, height.value)); const size = computed(() => shortSide.value / zoom.value); const crop = computed(() => ({ x: (width.value - size.value) * horizontal.value / shortSide.value, y: (height.value - size.value) * vertical.value / shortSide.value, size: size.value / shortSide.value }));
const imageStyle = computed(() => ({ width: `${width.value / size.value * 100}%`, height: `${height.value / size.value * 100}%`, left: `${-(width.value - size.value) * horizontal.value / size.value * 100}%`, top: `${-(height.value - size.value) * vertical.value / size.value * 100}%` }));
async function pick(event: Event) { const picked = (event.target as HTMLInputElement).files?.[0]; if (!picked) return; if (!['image/jpeg','image/png','image/webp'].includes(picked.type) || picked.size > 20 * 1024 * 1024) { error.value = '请选择不超过 20 MB 的 JPEG、PNG 或 WebP 图片。'; return; } error.value = ''; if (source.value) URL.revokeObjectURL(source.value); source.value = URL.createObjectURL(picked); const image = new Image(); image.src = source.value; try { await image.decode(); if (!active) return; width.value = image.naturalWidth; height.value = image.naturalHeight; file.value = picked; zoom.value = 1; horizontal.value = 0.5; vertical.value = 0.5; } catch { if (active) error.value = '图片无法读取，请换一张图片。'; } }
onBeforeUnmount(() => { active = false; if (source.value) URL.revokeObjectURL(source.value); file.value = undefined; source.value = ''; });
</script>
<template><Drawer title="编辑头像" subtitle="仅上传裁剪并加密后的头像" :busy="busy" @close="emit('close')"><div class="form-grid"><p class="muted">原图留在本机。保存时会校正方向、重新编码并检查元数据清除，再生成头像与缩略图。</p><label class="field"><span>选择图片</span><input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="pick"></label><p v-if="error || failure" class="error" role="alert">{{ error || failure }}</p><div v-if="file" class="crop-preview"><img :src="source" alt="头像裁剪预览" :style="imageStyle"></div><template v-if="file"><label class="field"><span>缩放</span><input v-model.number="zoom" type="range" min="1" max="4" step="0.01"></label><label class="field"><span>左右位置</span><input v-model.number="horizontal" type="range" min="0" max="1" step="0.01"></label><label class="field"><span>上下位置</span><input v-model.number="vertical" type="range" min="0" max="1" step="0.01"></label></template></div><template #footer><button class="button secondary" :disabled="busy" @click="emit('close')">取消</button><button class="button primary" :disabled="!file || busy" @click="file && emit('save', file, crop)">{{ busy ? '处理并加密…' : '保存头像' }}</button></template></Drawer></template>
